var NX={"en": {"nav.handmade": "Handmade", "nav.design": "Content design", "nav.projects": "Projects", "nav.learning": "Continuous learning", "nav.speaking": "Public speaking", "nav.cv": "Online CV", "logo.home": "iaracreates, home", "home.eyebrow2": "Content design · Handmade bags · Blaricum, Netherlands", "home.title2": "One thread, two crafts.", "home.lede2": "Alongside it, I sew and crochet one-of-a-kind bags and accessories by hand, from bold fabrics new and thrifted. One thread runs through both: lines that connect.", "btn.handmade": "Explore handmade", "btn.design": "See content design", "btn.readStory": "Read the full story", "home.handmadeL": "I love to create beautifully <mark class=\"hl\">odd</mark> things: bags and accessories, each one of a kind, sewn and crocheted in Blaricum.", "home.designL": "I transform ideas, goals and requirements into clear words that guide users in a human, relevant way.", "btn.allProjects": "All projects", "home.mAskT": "Have a project in mind, or saw a piece you love?", "home.mAskL": "Ask me about content design work, or about any piece. Nothing here is sold online, so just get in touch and I'll tell you more.", "d.ledeAdd": "I transform ideas, goals and requirements into clear words that guide users in a human, relevant way.", "d.btnProjects": "See projects", "d.moreT": "More from the content side", "ab.threadT": "The red thread", "ab.threadL": "My connection with my grandmother began with a red thread, and it has changed shape three times.", "ab.s1t": "A thread for the hiccups", "ab.s1p": "In Brazil, when a baby has the hiccups, someone places a little piece of red thread on their forehead. My grandmother Zélia did it for me. That's where our thread begins.", "ab.s2t": "First stitches", "ab.s2p": "Later, she taught me the basics of hand sewing so I could sew for my Barbie dolls. The thread became a skill, passed from her hands to mine.", "ab.s3t": "The thread today", "ab.s3p": "Her lessons still guide my hands. Now I sew with tools of my own choosing, and every piece still starts with what she taught me.", "ab.linesT": "Lines that connect", "ab.linesP": "In sewing, lines join pieces of fabric and give them shape. In content design, lines of UI copy join people to what they need and shape how a product feels. Bags or words, it's the same craft: connecting things so they hold together.", "ab.handT": "The handmade side", "ab.makerP": "Bags are my love project; content design is my profession. Both are made of lines that connect.", "ct.lede": "Questions about a piece, a custom bag, a market, a collaboration or content design work: write to me and I'll get back to you by email.", "ct.s6": "Content design work", "foot.zelda": "iaracreates"}, "pt": {"nav.handmade": "Feito à mão", "nav.design": "Content design", "nav.projects": "Projetos", "nav.learning": "Aprendizado contínuo", "nav.speaking": "Palestras", "nav.cv": "Currículo online", "logo.home": "iaracreates, início", "home.eyebrow2": "Content design · Bolsas feitas à mão · Blaricum, Holanda", "home.title2": "Uma linha, dois ofícios.", "home.lede2": "Junto com isso, costuro e faço em crochê, à mão, bolsas e acessórios únicos, com tecidos ousados, novos e de brechó. Uma linha passa pelos dois: linhas que conectam.", "btn.handmade": "Conheça as peças", "btn.design": "Ver content design", "btn.readStory": "Leia a história completa", "home.handmadeL": "Amo criar coisas lindamente <mark class=\"hl\">esquisitas</mark>: bolsas e acessórios, cada um único, costurados e feitos em crochê em Blaricum.", "home.designL": "Transformo ideias, objetivos e requisitos em palavras claras, que guiam os usuários de forma humana e relevante.", "btn.allProjects": "Todos os projetos", "home.mAskT": "Tem um projeto em mente, ou viu uma peça que amou?", "home.mAskL": "Me pergunta sobre trabalhos de content design, ou sobre qualquer peça. Nada aqui é vendido online, então é só me escrever que eu te conto mais.", "d.ledeAdd": "Transformo ideias, objetivos e requisitos em palavras claras, que guiam os usuários de forma humana e relevante.", "d.btnProjects": "Ver projetos", "d.moreT": "Mais do lado do conteúdo", "ab.threadT": "A linha vermelha", "ab.threadL": "A minha conexão com a minha vó começou com uma linha vermelha, e ela já mudou de forma três vezes.", "ab.s1t": "Uma linha pro soluço", "ab.s1p": "No Brasil, quando o bebê está com soluço, alguém coloca um pedacinho de linha vermelha na testa dele. Minha vó Zélia fazia isso comigo. É aí que começa a nossa linha.", "ab.s2t": "Primeiros pontos", "ab.s2p": "Depois, ela me ensinou o básico da costura à mão pra eu costurar pras minhas Barbies. A linha virou um ofício, passado das mãos dela pras minhas.", "ab.s3t": "A linha hoje", "ab.s3p": "Os ensinamentos dela ainda guiam as minhas mãos. Hoje eu costuro com as ferramentas que escolhi, e cada peça ainda começa com o que ela me ensinou.", "ab.linesT": "Linhas que conectam", "ab.linesP": "Na costura, as linhas unem pedaços de tecido e dão forma a eles. No content design, as linhas de texto da interface unem as pessoas ao que elas precisam e dão forma à experiência de um produto. Bolsas ou palavras, é o mesmo ofício: conectar as coisas pra que tudo se sustente.", "ab.handT": "O lado feito à mão", "ab.makerP": "As bolsas são meu projeto de amor; o content design é a minha profissão. Os dois são feitos de linhas que conectam.", "ct.lede": "Dúvidas sobre uma peça, uma bolsa personalizada, uma feira, uma parceria ou trabalhos de content design: me escreve e eu te respondo por e-mail.", "ct.s6": "Trabalhos de content design", "foot.zelda": "iaracreates"}, "nl": {"nav.handmade": "Handgemaakt", "nav.design": "Content design", "nav.projects": "Projecten", "nav.learning": "Continu leren", "nav.speaking": "Lezingen", "nav.cv": "Online cv", "logo.home": "iaracreates, home", "home.eyebrow2": "Content design · Handgemaakte tassen · Blaricum, Nederland", "home.title2": "Eén draad, twee ambachten.", "home.lede2": "Daarnaast naai en haak ik met de hand unieke tassen en accessoires, van gedurfde stoffen, nieuw en tweedehands. Eén draad loopt door allebei: lijnen die verbinden.", "btn.handmade": "Bekijk het handwerk", "btn.design": "Bekijk content design", "btn.readStory": "Lees het hele verhaal", "home.handmadeL": "Ik maak graag prachtig <mark class=\"hl\">eigenaardige</mark> dingen: tassen en accessoires, stuk voor stuk uniek, genaaid en gehaakt in Blaricum.", "home.designL": "Ik zet ideeën, doelen en eisen om in heldere woorden die gebruikers op een menselijke, relevante manier begeleiden.", "btn.allProjects": "Alle projecten", "home.mAskT": "Een project in gedachten, of een stuk gezien waar je verliefd op bent?", "home.mAskL": "Vraag me naar content design-werk, of naar een stuk. Hier wordt niets online verkocht, dus neem gerust contact op en ik vertel je meer.", "d.ledeAdd": "Ik zet ideeën, doelen en eisen om in heldere woorden die gebruikers op een menselijke, relevante manier begeleiden.", "d.btnProjects": "Bekijk projecten", "d.moreT": "Meer van de contentkant", "ab.threadT": "De rode draad", "ab.threadL": "De band met mijn oma begon met een rode draad, en die is al drie keer van vorm veranderd.", "ab.s1t": "Een draadje tegen de hik", "ab.s1p": "In Brazilië leg je een stukje rode draad op het voorhoofd van een baby met de hik. Mijn oma Zélia deed dat bij mij. Daar begint onze draad.", "ab.s2t": "Eerste steken", "ab.s2p": "Later leerde ze me de basis van handnaaien, zodat ik voor mijn Barbiepoppen kon naaien. De draad werd een vaardigheid, van haar handen naar de mijne.", "ab.s3t": "De draad nu", "ab.s3p": "Haar lessen sturen mijn handen nog steeds. Nu naai ik met gereedschap dat ik zelf heb gekozen, en elk stuk begint nog altijd bij wat zij me leerde.", "ab.linesT": "Lijnen die verbinden", "ab.linesP": "Bij het naaien verbinden lijnen stukken stof en geven ze vorm. In content design verbinden regels UI-tekst mensen met wat ze nodig hebben en geven ze vorm aan hoe een product voelt. Tassen of woorden, het is hetzelfde ambacht: dingen verbinden zodat ze een geheel vormen.", "ab.handT": "De handgemaakte kant", "ab.makerP": "Tassen zijn mijn liefdesproject, content design is mijn vak. Allebei zijn ze gemaakt van lijnen die verbinden.", "ct.lede": "Vragen over een stuk, een tas op maat, een markt, een samenwerking of content design-werk: schrijf me en ik antwoord je per e-mail.", "ct.s6": "Content design-werk", "foot.zelda": "iaracreates"}};
