/* ---------- Contact form: prototype only, nothing is sent anywhere ---------- */
var pending=null;
function bindContact(){
  var s=document.getElementById("f-subject"),m=document.getElementById("f-message");
  if(PROD&&!pending){var qs=new URLSearchParams(location.search);if(qs.get("piece"))pending={piece:qs.get("piece")};else if(qs.get("subject"))pending={subject:qs.get("subject")}}
  if(pending){
    if(pending.subject)s.value=pending.subject;
    if(pending.piece&&byId[pending.piece]){var pc=byId[pending.piece];
      if(pc.id==="custom-tote"){s.value="3";m.value=t("ct.preCustom")}else{s.value="2";m.value=t("ct.prePiece",{name:L(pc,"name")})}}
    pending=null}
  var cb=document.getElementById("copy-mail");
  cb.onclick=function(){var el=document.getElementById("mail");function sel(){var r=document.createRange();r.selectNodeContents(el);var x=getSelection();x.removeAllRanges();x.addRange(r);cb.textContent=t("ct.selected")}
    try{navigator.clipboard.writeText(el.textContent).then(function(){cb.textContent=t("ct.copied")},sel)}catch(e){sel()}setTimeout(function(){cb.textContent=t("ct.copy")},2200)};
  var form=document.getElementById("contact-form"),st=document.getElementById("f-status"),send=document.getElementById("f-send");
  function say(msg,cls){st.textContent=msg;st.className="status"+(cls?" "+cls:"")}
  form.addEventListener("submit",function(e){
    e.preventDefault();
    var name=form.name.value.trim(),email=form.email.value.trim(),msg=form.message.value.trim(),subject=T.en["ct.s"+form.subject.value];
    if(form._honey.value)return;
    if(!name||!msg||!/^\S+@\S+\.\S+$/.test(email)){say(t("ct.invalid"),"err");return}
    if(PROD){var body=msg+"\n\n"+name+" <"+email+">";location.href="mailto:iaracreates.info@gmail.com?subject="+encodeURIComponent(subject+" · iaracreates")+"&body="+encodeURIComponent(body);say(t("ct.mailto"),"ok");return}
    send.disabled=true;say(t("ct.sending"));
    setTimeout(function(){
      say({en:"Prototype preview: messages aren't sent from here. On the live site this goes to iaracreates.info@gmail.com.",
           pt:"Prévia do protótipo: as mensagens não são enviadas daqui. No site oficial, isso vai para iaracreates.info@gmail.com.",
           nl:"Prototype-preview: berichten worden hier niet verstuurd. Op de echte site gaat dit naar iaracreates.info@gmail.com."}[LANG],"ok");
      send.disabled=false;
    },500);
  });
}

