/* project filter: one focus area at a time, tap the active one again to show all */
var PFILTER="all";
function ptabs(){
  return '<div class="ptabs" role="group" aria-label="'+esc(pf("tabs_label"))+'">'+["uxui","journeys","strategy"].map(function(k){
    var n=PROJ.filter(function(p){return p.cats.indexOf(k)>=0}).length;
    return '<button type="button" data-tab="'+k+'" aria-pressed="'+(PFILTER===k)+'"><span>'+esc(pf("tab_"+k))+'</span><small>'+esc(fmt(pf("ui").count,{n:n}))+'</small></button>';
  }).join("")+'</div><p class="pstatus" id="pstatus" aria-live="polite"></p>';
}
function filteredIds(){return PROJ.filter(function(p){return PFILTER==="all"||p.cats.indexOf(PFILTER)>=0}).map(function(p){return p.id})}
function renderProjects(){
  var g=document.getElementById("pgrid-all");if(!g)return;
  var ids=filteredIds();g.dataset.ids=ids.join(",");g.innerHTML=ids.map(function(i){return pcard(proj(i))}).join("");
  document.getElementById("pstatus").textContent=PFILTER==="all"?fmt(pf("ui").status_all,{total:PROJ.length}):fmt(pf("ui").status_some,{n:ids.length,total:PROJ.length});
  document.querySelectorAll(".ptabs button").forEach(function(b){b.setAttribute("aria-pressed",String(b.dataset.tab===PFILTER))});
}

